const issues = items.map(i => i.json);

const rows = issues.map(issue => {
  const f = issue.fields || {};
  return {
    Key: issue.key,
    Type: f.issuetype?.name || 'Unknown',
    Status: f.status?.name || 'Unknown',
    Priority: f.priority?.name || 'n/a',
    Points: f.customfield_10016 ?? 'n/a',
    Summary: f.summary || ''
  };
});

const promptText = rows.map(r =>
  `- ${r.Key} | ${r.Type} | status: ${r.Status} | priority: ${r.Priority} | points: ${r.Points} | summary: ${r.Summary}`
).join('\n');

return [{ json: { issueCount: rows.length, summaryText: promptText, rows } }];

const formatted = $('Format Issues For Prompt').first().json;
const aiSummary = $json.output || '(no summary produced — check AI Agent node output field name)';

const summaryRow = {
  Key: 'AI SUMMARY',
  Type: '',
  Status: '',
  Priority: '',
  Points: '',
  Summary: aiSummary
};

return [summaryRow, ...formatted.rows].map(row => ({ json: row }));
